def load() -> pd.DataFrame:
    import glob
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201810??T235942_201810??T235942_0201/*.sp3'))
    lines = []
    with open(files[0], 'r') as f:
        for i, line in enumerate(f):
            if i >= 40:
                break
            lines.append({'line_no': i, 'content': line.rstrip()})
    return pd.DataFrame(lines)

def process(load_omni2) -> pd.DataFrame:
    df = load_omni2.copy()
    # Parse and normalize timestamp - remove timezone info
    df['Timestamp'] = pd.to_datetime(df['Timestamp'], utc=True).dt.tz_localize(None)
    mask = (df['Timestamp'] >= '2018-10-01') & (df['Timestamp'] < '2018-10-11')
    return df[mask].reset_index(drop=True)
